import React, { useCallback, useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { Activity, ArrowDownToLine, ArrowRight, AudioLines, Check, CheckCircle2, ChevronRight, CircleHelp, Copy, Headphones, LayoutDashboard, Link2, LoaderCircle, LockKeyhole, MessageSquare, Mic2, Pause, Play, Plus, Radio, Search, Settings2, ShieldCheck, SlidersHorizontal, Sparkles, Square, Terminal, Trash2, Upload, Users, Volume2, VolumeX, WandSparkles, X } from 'lucide-react';
import type { Settings, Voice, Viewer, LogEntry } from '../server/types';
import type { Design, Job } from '../server/engine';
import { eventTypes, eventLabels, eventDescriptions, interactionLabels, interactionExamples, type EventType, type InteractionAction } from '../shared/events';
import { resumeAudio } from './audio';
import './styles.css';
import { VoiceSyncPanel } from './VoiceSyncPanel';
import { AnalyticsDashboard } from './AnalyticsDashboard';

type Status = { settings: Settings; bridgeConnections: number; playerActive: boolean; lastEventAt: string | null; queue: Job[]; pending: number; totalViewers: number; todaySpeech: number; todayChars: number; used: number; cloneUsed: number; pendingDesigns: number; configured: boolean };
type Page = 'overview' | 'analytics' | 'events' | 'voices' | 'viewers' | 'designs' | 'logs' | 'settings';
let adminToken = '';
class RequestError extends Error { constructor(message: string, public status: number) { super(message); } }
async function request(path: string, body?: unknown, method = body === undefined ? 'GET' : 'POST', signal?: AbortSignal) {
  const response = await fetch(`/api${path}`, { method, headers: { 'Content-Type': 'application/json', 'X-DMReader-Admin': adminToken }, ...(body === undefined ? {} : { body: JSON.stringify(body) }), signal });
  if (!response.ok) { const error = await response.json().catch(() => ({})); throw new RequestError(error.error || `请求失败 (${response.status})`, response.status); }
  return response;
}
async function api<T = Record<string, unknown>>(path: string, body?: unknown, method?: string): Promise<T> { return (await request(path, body, method)).json(); }
const fmt = (n: number) => n.toLocaleString('zh-CN');
const time = (s: string) => new Date(s).toLocaleTimeString('zh-CN', { hour12: false });
const nav: { id: Page; title: string; icon: typeof Radio; sub: string }[] = [
  { id: 'overview', title: '直播控制台', icon: LayoutDashboard, sub: '让每一条弹幕，都有自己的声音。' },
  { id: 'analytics', title: '数据看板', icon: Activity, sub: '看见直播间的热度，也看清每一份声音的消耗。' },
  { id: 'events', title: '事件播报', icon: Radio, sub: '选择要读出的互动，让直播间热闹得刚刚好。' },
  { id: 'voices', title: '音色实验室', icon: AudioLines, sub: '选一个声音，为直播间添一点性格。' },
  { id: 'viewers', title: '观众档案', icon: Users, sub: '记住声音，也记住每一次相遇。' },
  { id: 'designs', title: '专属音色', icon: WandSparkles, sub: '用一段描述，创造观众自己的声音。' },
  { id: 'logs', title: '活动记录', icon: Activity, sub: '每条指令、每次合成，都有迹可循。' },
  { id: 'settings', title: '接入与设置', icon: Settings2, sub: '连接直播间，调整你的播报习惯。' },
];
function Badge({ children, tone = '' }: { children: React.ReactNode; tone?: string }) { return <span className={`badge ${tone}`}>{children}</span>; }
function Empty({ icon: Icon = MessageSquare, title, children }: { icon?: typeof Radio; title: string; children?: React.ReactNode }) { return <div className="empty"><span><Icon size={28} strokeWidth={1.5} /></span><h3>{title}</h3><p>{children}</p></div>; }
function Field({ label, hint, children }: { label: string; hint?: string; children: React.ReactNode }) { return <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
function Toggle({ value, onChange, title, detail }: { value: boolean; onChange: (v: boolean) => void; title: string; detail?: string }) { return <label className="toggle-row"><span><b>{title}</b>{detail && <small>{detail}</small>}</span><input type="checkbox" role="switch" checked={value} onChange={e => onChange(e.target.checked)} /><span className="switch" /></label>; }
function Modal({ title, children, close }: { title: string; children: React.ReactNode; close: () => void }) { return <div className="modal-shade" onClick={close}><section role="dialog" aria-modal="true" aria-label={title} className="modal" onClick={e => e.stopPropagation()}><div className="card-head"><h2>{title}</h2><button className="icon-button" aria-label="关闭弹窗" onClick={close}><X size={20} /></button></div>{children}</section></div>; }
function App() {
  const [status, setStatus] = useState<Status | null>(null), [page, setPage] = useState<Page>(location.hash === '#analytics' ? 'analytics' : 'overview');
  const [voices, setVoices] = useState<Voice[]>([]), [logs, setLogs] = useState<LogEntry[]>([]);
  const [toast, setToast] = useState(''), [fatal, setFatal] = useState(''), [busy, setBusy] = useState('');
  const [playerState, setPlayerState] = useState<'waiting' | 'starting' | 'blocked' | 'playing' | 'other' | 'stopped' | 'error'>('waiting');
  const playing = playerState === 'playing';
  const [now, setNow] = useState<{ username: string; text: string; voice: string } | null>(null);
  const [volume, setVolume] = useState(Number(localStorage.getItem('dmreader-volume') ?? 80));
  const [help, setHelp] = useState(false);
  const playerSession = useRef(''), running = useRef(false), aborter = useRef<AbortController | null>(null);
  const playbackRun = useRef(0), starting = useRef(false), manuallyStopped = useRef(false), previewing = useRef(false);
  const canPlay = !!status && status.settings.enabled && status.settings.mode === 'bridge' && status.configured;
  const canPlayRef = useRef(canPlay); canPlayRef.current = canPlay;
  const gestureStart = useRef(() => {});
  const audio = useRef<AudioContext | null>(null), gain = useRef<GainNode | null>(null), source = useRef<AudioBufferSourceNode | null>(null);
  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const notify = useCallback((message: string) => { setToast(message); if (toastTimer.current) clearTimeout(toastTimer.current); toastTimer.current = setTimeout(() => setToast(''), 6000); }, []);
  async function refresh() { const [s, l] = await Promise.all([api<Status>('/status'), api<LogEntry[]>('/logs')]); setStatus(s); setLogs(l); setFatal(''); }
  useEffect(() => {
    let disposed = false;
    fetch('/api/bootstrap').then(r => r.json()).then(async data => {
      if (!data.adminToken) throw new Error(data.error || '后台启动失败');
      adminToken = data.adminToken; if (disposed) return; setStatus(data.status);
      setVoices(await api<Voice[]>('/voices')); await refresh();
    }).catch(e => setFatal(e.message));
    const poll = setInterval(() => { if (adminToken) void refresh().catch(e => setFatal(e.message)); }, 3000);
    const unload = () => {
      stop(false, true);
    };
    window.addEventListener('pagehide', unload);
    return () => { disposed = true; clearInterval(poll); window.removeEventListener('pagehide', unload); unload(); void audio.current?.close(); };
  }, []);
  useEffect(() => { if (gain.current) gain.current.gain.value = volume / 100; localStorage.setItem('dmreader-volume', String(volume)); }, [volume]);
  useEffect(() => {
    if (!playing) return;
    const run = playbackRun.current, session = playerSession.current;
    const heartbeat = setInterval(() => { if (running.current && run === playbackRun.current) void api('/player/heartbeat', { session }).catch(e => { if (run === playbackRun.current) { stop(false); setPlayerState('error'); notify(e.message); } }); }, 5000);
    return () => clearInterval(heartbeat);
  }, [playing]);
  useEffect(() => {
    if (!canPlay) { if (running.current || starting.current) stop(false); return; }
    if (!fatal && !busy) void start();
  }, [status, fatal, busy]);
  gestureStart.current = () => {
    if (!canPlayRef.current || manuallyStopped.current || previewing.current || running.current) return;
    // Call resume in the gesture itself, even if an earlier automatic attempt is pending.
    if (starting.current) { void audio.current?.resume().catch(() => {}); return; }
    if (status?.playerActive) void unlockAudio().catch(() => {});
    void start(false, true);
  };
  useEffect(() => {
    const activate = (event: Event) => { if (event.isTrusted) gestureStart.current(); };
    window.addEventListener('click', activate);
    window.addEventListener('keydown', activate);
    window.addEventListener('touchend', activate);
    return () => { window.removeEventListener('click', activate); window.removeEventListener('keydown', activate); window.removeEventListener('touchend', activate); };
  }, []);
  async function unlockAudio() {
    if (!audio.current || audio.current.state === 'closed') {
      audio.current = new AudioContext(); gain.current = audio.current.createGain(); gain.current.gain.value = volume / 100; gain.current.connect(audio.current.destination);
      audio.current.onstatechange = () => { if (running.current && audio.current?.state !== 'running') { stop(false); setPlayerState('blocked'); } };
    }
    return resumeAudio(audio.current);
  }
  async function playBuffer(data: ArrayBuffer, run?: number) {
    const decoded = await audio.current!.decodeAudioData(data);
    if (run !== undefined && run !== playbackRun.current) return;
    const node = audio.current!.createBufferSource(); node.buffer = decoded; node.connect(gain.current!); source.current = node;
    await new Promise<void>(resolve => { node.onended = () => resolve(); node.start(); });
    if (source.current === node) source.current = null;
  }
  function stop(manual = true, keepalive = false) {
    if (manual) manuallyStopped.current = true;
    playbackRun.current++; running.current = false; setPlayerState(manuallyStopped.current ? 'stopped' : 'waiting'); aborter.current?.abort(); source.current?.stop(); source.current = null; setNow(null);
    const session = playerSession.current; playerSession.current = '';
    if (session) void fetch('/api/player/release', { method: 'POST', keepalive, headers: { 'Content-Type': 'application/json', 'X-DMReader-Admin': adminToken }, body: JSON.stringify({ session }) }).catch(() => {});
  }
  async function start(manual = false, gesture = false) {
    if (manual) manuallyStopped.current = false;
    if (!canPlayRef.current || previewing.current || manuallyStopped.current || running.current || starting.current || (!manual && playerState === 'error')) return;
    if (status?.playerActive) { setPlayerState('other'); return; }
    if (!manual && !gesture && playerState === 'blocked' && audio.current?.state !== 'running') return;
    starting.current = true; const run = ++playbackRun.current;
    setPlayerState('starting');
    const session = crypto.randomUUID();
    try {
      const ready = await unlockAudio();
      if (run !== playbackRun.current || !canPlayRef.current || manuallyStopped.current) return;
      if (!ready) { setPlayerState('blocked'); return; }
      await api('/player/claim', { session });
      if (run !== playbackRun.current || !canPlayRef.current || manuallyStopped.current) { await api('/player/release', { session }); return; }
      playerSession.current = session; running.current = true; setPlayerState('playing');
      while (running.current && run === playbackRun.current) {
        if (audio.current?.state !== 'running') { stop(false); setPlayerState('blocked'); break; }
        aborter.current = new AbortController();
        const r = await request('/player/next', { session }, 'POST', aborter.current.signal);
        if (!running.current || run !== playbackRun.current) break;
        if (r.status === 204) { await new Promise(r => setTimeout(r, 900)); continue; }
        const job = JSON.parse(decodeURIComponent(r.headers.get('X-DMReader-Job') || '{}'));
        const data = await r.arrayBuffer(); if (!running.current || run !== playbackRun.current) break;
        setNow(job); await playBuffer(data, run); if (run !== playbackRun.current) break; setNow(null); void refresh().catch(() => {});
      }
    } catch (e) {
      if (run === playbackRun.current && (e as Error).name !== 'AbortError') {
        stop(false);
        if (e instanceof RequestError && e.status === 409) setPlayerState('other');
        else { setPlayerState('error'); notify((e as Error).message); }
      }
    }
    finally { starting.current = false; }
  }
  async function action(name: string, fn: () => Promise<unknown>, message?: string) {
    setBusy(name); try { await fn(); await refresh(); if (message) notify(message); return true; } catch (e) { notify((e as Error).message); return false; } finally { setBusy(''); }
  }
  async function preview(text: string, voice: string, style: string, speed: number) {
    if (playing) { notify('请先停止直播播放器，再进行试听。'); return; }
    previewing.current = true; stop();
    try { await action('preview', async () => { if (!await unlockAudio()) throw new Error('浏览器尚未允许声音播放，请再次点击试听。'); const r = await request('/preview', { text, voice, style, speed }); setNow({ username: '音色试听', text, voice: voices.find(v => v.id === voice)?.name || voice }); try { await playBuffer(await r.arrayBuffer()); } finally { setNow(null); } }); }
    finally { previewing.current = false; }
  }
  async function saveSettings(patch: Partial<Settings>) { return action('settings', () => api('/settings', patch, 'PATCH'), '设置已保存'); }
  async function reloadVoices() { setVoices(await api<Voice[]>('/voices')); }
  if (!status) return <div className="boot"><div className="brand-symbol"><AudioLines /></div><h1>DM Reader</h1><p>{fatal || '正在唤醒直播间的声音…'}</p>{fatal && <button onClick={() => location.reload()}>重新连接</button>}</div>;
  const s = status.settings, current = nav.find(n => n.id === page)!;
  const playerTitle = playing ? '播放器就绪，等待下一条弹幕' : !canPlay ? !s.enabled ? '播报已暂停' : s.mode !== 'bridge' ? '当前由 LAPLACE 播放' : '等待配置语音服务' : ({ waiting: '正在准备自动播放', starting: '正在启动播放器', blocked: '点击页面任意位置，即可启用声音', other: '另一个后台页面正在播放', stopped: '本页面已手动停止播放', error: '播放器连接异常，请重试' } as const)[playerState];
  const playerDetail = playing ? '保持此页面开启，弹幕将自动播报。' : playerState === 'blocked' ? '浏览器暂未允许自动播放；点击或按键后会自动开启，无需寻找开关。' : playerState === 'other' ? '此页面会等待播放权限释放，避免重复播报。' : playerState === 'stopped' ? '点击恢复播放即可继续；重新打开或刷新页面时默认自动开启。' : '页面打开后默认尝试开启播放器。';
  return <div className="app-shell">
    <aside className="sidebar"><a className="brand" href="/" aria-label="DM Reader 首页"><span className="brand-symbol"><AudioLines size={25} /></span><span>DM Reader<small>让弹幕，自带声场</small></span></a><div className="nav-label">WORKSPACE</div><nav>{nav.map(n => <button key={n.id} className={page === n.id ? 'nav active' : 'nav'} onClick={() => setPage(n.id)}><n.icon size={19} /><span>{n.title}</span>{n.id === 'designs' && status.pendingDesigns > 0 && <i>{status.pendingDesigns}</i>}{page === n.id && <span className="nav-dot" />}</button>)}</nav><div className="sidebar-bottom"><div className="local-note"><ShieldCheck size={17} /><span>本地运行 · 偏好留在本机</span></div><button className="help-button" onClick={() => setHelp(true)}><CircleHelp size={18} />使用指南<ChevronRight size={15} /></button><small className="version">DM Reader 0.1 · Doubao TTS 2.0</small></div></aside>
    <main><header className="topbar"><div className="breadcrumb">工作空间 <ChevronRight size={14} /> <b>{current.title}</b></div><div className="top-right"><Badge tone={status.bridgeConnections ? 'green' : ''}><span className={`dot ${status.bridgeConnections ? 'green-dot' : ''}`} />{status.bridgeConnections ? '弹幕桥已连接' : '等待弹幕连接'}</Badge><span className="room-label">房间 {s.roomId}</span><span className="avatar">Y</span></div></header>
    <div className="main-content"><div className="page-heading"><div><div className="eyebrow">{page === 'overview' ? 'YOUR LIVE, YOUR VOICE' : 'DM READER / STUDIO'}</div><h1>{current.title}<span className="heading-dot">.</span></h1><p>{current.sub}</p></div><button className="button secondary" onClick={() => setHelp(true)}><CircleHelp size={16} />使用指南</button></div>
      {fatal && <div role="alert" className="notice danger">连接中断：{fatal}<button onClick={() => location.reload()}>刷新后台</button></div>}
      {canPlay && !playing && <div role="status" className="notice player-notice"><div className="notice-icon"><Volume2 size={20} /></div><div><b>{playerTitle}</b><p>{playerDetail}</p></div>{playerState !== 'other' && <button className="button secondary" disabled={playerState === 'starting' || busy === 'preview'} onClick={() => void start(true)}>{playerState === 'stopped' ? '恢复播放' : playerState === 'error' ? '重试播放' : '启用声音'}</button>}</div>}
      {!status.configured && <div className="notice"><div className="notice-icon"><Link2 size={20} /></div><div><b>还差一步，让声音上线</b><p>填入火山引擎 API Key，即可试听与播报。观众指令和偏好保存已经可用。</p></div><button className="text-button" onClick={() => setPage('settings')}>前往接入 <ArrowRight size={16} /></button></div>}
      {page === 'overview' && <>
        <div className="stats-grid"><Stat icon={MessageSquare} label="今日合成" value={fmt(status.todaySpeech)} unit="条" note="含缓存复用与试听" /><Stat icon={Users} label="记住的观众" value={fmt(status.totalViewers)} unit="位" note="按 UID 持久保存" /><Stat icon={AudioLines} label="等待播报" value={fmt(status.queue.length)} unit={`/ ${s.maxQueue}`} note={s.enabled ? '队列有序播放' : '播报已暂停'} /><Stat icon={ShieldCheck} label="本地可用字数" value={fmt(Math.max(0, s.budget - status.used))} unit="字" note="保护上限 · 非云端余额" /></div>
        <div className="dashboard-grid"><section className="live-card"><div className="live-card-top"><Badge tone="glass"><span className={`dot ${playing ? 'green-dot' : ''}`} />{playing ? 'PLAYER ON' : 'AUTO PLAY'}</Badge><span>LIVE ROOM / {s.roomId}</span></div><div className="live-title"><h2>{playing ? '弹幕正在发声' : '给弹幕，开个麦。'}</h2><p>{s.mode === 'bridge' ? '每个人的声音，从这里被记住。' : '当前由 LAPLACE 自定义 API 负责播放。'}</p></div><div className={`wave ${playing && now ? 'animate' : ''}`}>{Array.from({ length: 39 }, (_, i) => <span key={i} style={{ height: `${13 + Math.sin(i * 1.2) ** 2 * (i > 10 && i < 29 ? 76 : 37)}px`, animationDelay: `${i * .04}s` }} />)}</div><div className="live-controls"><button className="button light" disabled={!canPlay || playerState === 'starting' || busy === 'preview'} onClick={() => playing ? stop() : void start(true)}>{playing ? <Square size={17} fill="currentColor" /> : <Play size={17} fill="currentColor" />}{playing ? '停止播放' : playerState === 'stopped' ? '恢复播放' : '启用声音'}</button><span>{playing ? '默认自动播放 · 保持页面开启' : playerTitle}</span><button className="icon-button light-icon" title="暂停或恢复服务" onClick={() => void saveSettings({ enabled: !s.enabled })}>{s.enabled ? <Pause size={19} /> : <Play size={19} />}</button></div></section>
        <section className="card connect-card"><div className="card-head"><h2>连接状态</h2><button className="icon-button" aria-label="打开接入设置" onClick={() => setPage('settings')}><SlidersHorizontal size={17} /></button></div><Connection ok={status.bridgeConnections > 0} title="LAPLACE 弹幕桥" detail={status.bridgeConnections ? `${status.bridgeConnections} 个事件源已接入` : '等待 Event Bridge 连接'} /><Connection ok={status.configured} title="豆包语音 2.0" detail={status.configured ? '凭据已保存 · 可开始试听' : '尚未配置 API 凭据'} /><Connection ok={playing} title="本地播放器" detail={playing ? '默认自动播放 · 正在接收播放任务' : playerTitle} /><div className="connect-foot"><LockKeyhole size={14} />服务仅监听本机 127.0.0.1</div></section></div>
        <div className="dashboard-grid lower"><section className="card"><div className="card-head"><h2>弹幕动态 <Badge>{logs.length ? '最近记录' : '等待中'}</Badge></h2><button className="text-button" onClick={() => setPage('logs')}>查看全部 <ArrowRight size={15} /></button></div>{logs.length ? <LogList logs={logs.slice(0, 5)} compact /> : <Empty title="第一条有声弹幕，等你开启">连接 LAPLACE 后，互动指令和播报记录会出现在这里。</Empty>}</section><section className="card command-card"><div className="card-head"><h2>把选择权交给观众</h2><Sparkles size={19} /></div><p>发送弹幕即可设置，下次来依然记得。</p><div className="command-row"><code>#音色 小何</code><span>换个声音</span></div><div className="command-row"><code>#风格 开心俏皮地说</code><span>赋予性格</span></div><div className="command-row"><code>#语速 1.2</code><span>调整节奏</span></div><div className="command-row"><code>#定制 温柔的成年女声</code><span>申请专属</span></div><button className="text-button" onClick={() => setHelp(true)}>查看全部指令 <ArrowRight size={15} /></button></section></div>
      </>}
      {page === 'analytics' && <AnalyticsDashboard api={api} room={s.roomId} />}
      {page === 'events' && <EventSettings settings={s} save={saveSettings} />}
      {page === 'voices' && <Voices reloadVoices={reloadVoices} voices={voices} settings={s} busy={busy} preview={preview} save={saveSettings} />}
      {page === 'viewers' && <Viewers voices={voices} settings={s} notify={notify} action={action} />}
      {page === 'designs' && <Designs action={action} reloadVoices={reloadVoices} busy={busy} />}
      {page === 'logs' && <Logs logs={logs} />}
      {page === 'settings' && <SettingsPanel status={status} voices={voices} save={saveSettings} action={action} notify={notify} />}
      <footer className="page-footer"><span><span className="dot green-dot" /> 在你的电脑上运行</span><span>把普通的相遇，变成有声的记忆。</span></footer>
    </div>
    <div className="player-bar"><span className={`player-glyph ${playing ? 'on' : ''}`}><AudioLines size={22} /></span><div className="player-info"><b>{now ? `${now.username} · ${now.voice}` : playerTitle}</b><span>{now?.text || playerDetail}</span></div><div className="player-actions">{playing && <Badge tone="green">正在监听</Badge>}<button className="icon-button" aria-label={volume ? '静音播放器' : '取消静音播放器'} onClick={() => setVolume(volume ? 0 : 80)}>{volume ? <Volume2 size={18} /> : <VolumeX size={18} />}</button><input aria-label="播放器音量" type="range" min="0" max="100" value={volume} onChange={e => setVolume(+e.target.value)} /><span>{volume}%</span><button className="icon-button" aria-label="清空待播队列" onClick={() => void action('clear', () => api('/queue/clear', {}), '待播队列已清空')}><Trash2 size={17} /></button></div></div>
    </main>{toast && <div role="status" className="toast"><CheckCircle2 size={18} /><span>{toast}</span><button className="icon-button" aria-label="关闭提示" onClick={() => setToast('')}><X size={16} /></button></div>}
    {help && <Modal title="让直播间的每个人，都有自己的声音" close={() => setHelp(false)}><div className="guide"><p>推荐使用「精准互动模式」：LAPLACE 接收弹幕 → Event Bridge 传递 UID → DM Reader 记住偏好并播放。请保持本后台页面开启，并关闭 LAPLACE 自带的自动语音播报。</p><div className="help-table">{[['#音色 小何', '支持短名、带 2.0 的名称、完整 ID 或被截断的 ID 前缀；多个匹配取目录中第一个。'], ['#风格 开心俏皮地说', '调整官方音色的表达方式；“#风格 清除”恢复默认。'], ['#语速 1.2', '0.5～2 倍，永久记住。'], ['#定制 温柔的成年女声', '提交新音色申请；主播在后台选择空槽位并生成。'], ['#查询 / #我的音色', '语音回报当前音色、语速和风格；查询播报至少冷却 10 秒。'], ['#音色列表 / #帮助', '结果显示在后台活动记录。'], ['#重置', '恢复直播间默认设置。']].map(([cmd, detail]) => <div key={cmd}><code>{cmd}</code><p>{detail}</p></div>)}</div><p>指令前缀支持 #、＃、!、！。修改指令默认冷却 10 秒。设置成功后播报确认文案，不直接读出原始指令。按稳定 UID 保存；缺少 UID 的普通弹幕会跳过，其他有效事件使用默认声音。相同内容可复用本地音频，避免重复扣量。</p><p>「风格」改变表达方式；「专属音色」会调用火山音色设计 API，占用声音复刻槽位和更新次数，并使用独立的复刻资源。它们与标准 TTS 字数包不同。</p><div className="links"><a href="https://laplace.live/chat/event-bridge" target="_blank" rel="noreferrer">LAPLACE 接入说明 ↗</a><a href="https://docs.volcengine.com/docs/DoubaoVoice/SoundDesignAPI?lang=zh" target="_blank" rel="noreferrer">火山音色设计文档 ↗</a></div></div></Modal>}
  </div>;
}
function Stat({ icon: Icon, label, value, unit, note }: { icon: typeof Radio; label: string; value: string; unit: string; note: string }) { return <div className="stat"><div className="stat-label">{label}<Icon size={17} /></div><div className="stat-value">{value}<small>{unit}</small></div><span>{note}</span></div>; }
function Connection({ ok, title, detail }: { ok: boolean; title: string; detail: string }) { return <div className="connection"><span className={`connection-check ${ok ? 'ok' : ''}`}>{ok ? <Check size={15} /> : <span />}</span><div><b>{title}</b><small>{detail}</small></div><span className={`dot ${ok ? 'green-dot' : ''}`} /></div>; }
const kindName: Record<string, string> = { speech: '已合成', cached: '缓存复用', command: '互动指令', 'command-error': '指令提示', skipped: '已跳过', error: '合成失败', design: '音色设计', 'bridge-error': '事件异常', queued: '已排队', disabled: '关闭播报', duplicate: '重复事件', invalid: '字段异常', cooldown: '冷却跳过', 'identity-fallback': '默认声音' };
function LogList({ logs, compact }: { logs: LogEntry[]; compact?: boolean }) { return <div className={`log-list ${compact ? 'compact' : ''}`}>{logs.map(l => <div className="log-row" key={l.id}><span className={`log-icon ${l.kind.includes('error') ? 'error' : ''}`}>{l.kind === 'command' ? <Terminal size={16} /> : <MessageSquare size={16} />}</span><div className="log-main"><div><b>{l.username || '系统'}</b><Badge tone={l.kind.includes('error') ? 'red' : l.kind === 'command' ? 'purple' : ''}>{kindName[l.kind] || l.kind}</Badge>{l.eventType && <span className="log-event-type">{l.eventType === 'command' ? '指令反馈' : eventLabels[l.eventType as EventType] || l.eventType}</span>}{l.voice && <span className="log-voice">{l.voice}</span>}</div>{l.text && <p>{l.text}</p>}<small>{l.detail}{!compact && l.uid ? ` · UID ${l.uid}` : ''}</small></div><div className="log-meta"><time>{time(l.time)}</time>{l.chars > 0 && <small>{l.chars} 字 · {l.latency} ms</small>}</div></div>)}</div>; }
function Voices({ voices, settings, busy, preview, save, reloadVoices }: { reloadVoices: () => Promise<void>; voices: Voice[]; settings: Settings; busy: string; preview: (t: string, v: string, s: string, speed: number) => Promise<void>; save: (s: Partial<Settings>) => Promise<boolean> }) {
  const [query, setQuery] = useState(''), [filter, setFilter] = useState('全部'), [language, setLanguage] = useState('全部语种'), [selected, setSelected] = useState(settings.defaultVoice);
  const [content, setContent] = useState('欢迎来到直播间，很高兴听见你的声音。'), [style, setStyle] = useState(''), [speed, setSpeed] = useState(0);
  const list = voices.filter(v => `${v.name} ${v.id} ${v.tag} ${v.language || ''} ${v.scenes?.join(' ') || ''} ${v.aliases?.join(' ') || ''}`.toLowerCase().includes(query.toLowerCase()) && (filter === '全部' || [v.gender, v.tag, ...(v.scenes || [])].includes(filter)) && (language === '全部语种' || v.language === language));
  return <div className="voice-layout"><section><VoiceSyncPanel api={api} reload={reloadVoices} /><div className="toolbar"><div className="search"><Search size={17} /><input placeholder="搜索名称、语种、角色或音色 ID" aria-label="搜索音色" value={query} onChange={e => setQuery(e.target.value)} /></div><Badge>{voices.length} 个音色</Badge></div><div className="filter-row">{['全部', '女声', '男声', '角色扮演', '有声阅读', '外语音色', '专属'].map(f => <button key={f} className={filter === f ? 'selected' : ''} onClick={() => setFilter(f)}>{f}</button>)}</div><select className="voice-language-filter" aria-label="筛选语种" value={language} onChange={e => setLanguage(e.target.value)}><option>全部语种</option>{[...new Set(voices.map(v => v.language).filter((x): x is string => !!x))].sort().map(l => <option key={l}>{l}</option>)}</select><div className="voice-grid">{list.map(v => <button key={v.id} onClick={() => setSelected(v.id)} className={`voice-card ${selected === v.id ? 'selected' : ''}`}><span className={`voice-avatar ${v.gender === '男声' ? 'blue' : v.gender === '专属' ? 'orange' : ''}`}><AudioLines size={25} /></span><div><h3>{v.name}{v.id === settings.defaultVoice && <span className="default-tag">默认</span>}</h3><p>{v.gender} · {v.language || v.tag}</p></div><span className="voice-radio">{selected === v.id && <Check size={13} />}</span></button>)}</div>{!list.length && <Empty title="没有匹配的音色">换一个关键词试试。</Empty>}<p className="muted source-note">当前收录 {voices.filter(v => v.resource === 'seed-tts-2.0').length} 个官方 2.0 音色，包含主表和外语表。实际调用权限以你的火山资源包为准。<a href="https://docs.volcengine.com/docs/DoubaoVoice/Tonelist-1?lang=zh" target="_blank" rel="noreferrer">官方音色表 ↗</a></p></section><aside className="card preview-card"><div className="card-head"><h2>声音试验台</h2><Headphones size={19} /></div><div className="preview-selected"><span className="voice-avatar"><AudioLines size={34} /></span><h2>{voices.find(v => v.id === selected)?.name}</h2><p>{voices.find(v => v.id === selected)?.description}</p></div><Field label="试听文本"><textarea rows={3} value={content} maxLength={settings.maxChars} onChange={e => setContent(e.target.value)} /></Field><Field label="说话风格" hint="专属音色保留设计时的声音，不附加风格指令。"><textarea rows={2} placeholder="例如：温柔、带一点笑意" value={style} maxLength={200} onChange={e => setStyle(e.target.value)} /></Field><Field label={`语速 · ${(1 + speed / 100).toFixed(1)} 倍`}><input type="range" min="-50" max="100" step="10" value={speed} onChange={e => setSpeed(+e.target.value)} /></Field><button className="button primary full" disabled={busy === 'preview' || !content.trim()} onClick={() => void preview(content, selected, style, speed)}>{busy === 'preview' ? <LoaderCircle className="spin" size={17} /> : <Play size={17} />}{busy === 'preview' ? '合成 / 播放中…' : '试听这个声音'}</button><button className="button secondary full" disabled={selected === settings.defaultVoice} onClick={() => void save({ defaultVoice: selected })}>设为直播间默认</button><p className="caption">试听会使用对应服务的字数额度。相同内容、音色和风格在一小时内复用缓存。</p><div className="command-copy"><span>观众可以这样选择</span><code>#音色 {voices.find(v => v.id === selected)?.name}</code></div></aside></div>;
}
type Action = (name: string, fn: () => Promise<unknown>, message?: string) => Promise<boolean>;
function Viewers({ voices, settings, notify, action }: { voices: Voice[]; settings: Settings; notify: (s: string) => void; action: Action }) {
  const [viewers, setViewers] = useState<Viewer[]>([]), [query, setQuery] = useState(''), [editing, setEditing] = useState<Viewer | null>(null), [simulate, setSimulate] = useState(false);
  const [sim, setSim] = useState({ uid: 'test-viewer', username: '本地测试观众', text: '#音色 小何' });
  async function load() { setViewers(await api<Viewer[]>(`/viewers?search=${encodeURIComponent(query)}`)); }
  useEffect(() => { void load().catch(e => notify(e.message)); const timer = setInterval(() => void load().catch(() => {}), 5000); return () => clearInterval(timer); }, [query]);
  async function backup() { const r = await request('/backup'); const url = URL.createObjectURL(await r.blob()); const a = document.createElement('a'); a.href = url; a.download = 'dmreader-profiles.json'; a.click(); URL.revokeObjectURL(url); }
  async function restore(file?: File) { if (!file) return; if (file.size > 1024 * 1024) { notify('备份不能超过 1 MB。'); return; } await action('import', async () => { const data = JSON.parse(await file.text()); await api('/backup', data); await load(); }, '档案已合并导入'); }
  return <><div className="toolbar"><div className="search"><Search size={17} /><input aria-label="搜索观众" placeholder="搜索昵称或 UID" value={query} onChange={e => setQuery(e.target.value)} /></div><div className="button-group"><button className="button secondary" onClick={() => void backup().catch(e => notify(e.message))}><ArrowDownToLine size={16} />导出偏好</button><label className="button secondary file-button"><Upload size={16} />导入<input aria-label="导入偏好备份" type="file" accept=".json" onChange={e => { void restore(e.target.files?.[0]); e.target.value = ''; }} /></label><button className="button primary" onClick={() => setSimulate(true)}><Terminal size={16} />测试指令</button></div></div><section className="card table-card"><div className="table-wrap"><table><thead><tr><th>观众</th><th>专属配置</th><th>语速</th><th>状态</th><th>最近出现</th><th /></tr></thead><tbody>{viewers.map(v => <tr key={v.uid}><td><div className="person"><span className="avatar lavender">{v.username.slice(0, 1)}</span><div><b>{v.username}</b><small>UID {v.uid}</small></div></div></td><td><b>{voices.find(x => x.id === (v.voice || settings.defaultVoice))?.name || '默认'}</b><small className="truncate">{v.style || '跟随默认风格'}</small></td><td>{1 + (v.speed ?? settings.speechRate) / 100}×</td><td><Badge tone={v.muted ? 'red' : v.locked ? 'purple' : 'green'}>{v.muted ? '已静音' : v.locked ? '已锁定' : '可互动'}</Badge></td><td className="muted">{new Date(v.lastSeen).toLocaleString('zh-CN')}</td><td><button className="text-button" onClick={() => setEditing({ ...v })}>管理</button></td></tr>)}</tbody></table></div>{!viewers.length && <Empty icon={Users} title="还没有观众档案">收到带有 UID 的弹幕后会自动创建；也可以先用本地测试指令体验。</Empty>}<div className="table-foot">显示 {viewers.length} 位观众 · 每次最多展示 500 位，可按 UID 搜索 · 导出包含全部档案</div></section>
    {editing && <Modal title={`管理 ${editing.username}`} close={() => setEditing(null)}><p className="muted">UID {editing.uid}</p><Field label="音色"><select value={editing.voice} onChange={e => setEditing({ ...editing, voice: e.target.value })}><option value="">跟随直播间默认</option>{voices.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}</select></Field><Field label="个人风格"><textarea maxLength={200} value={editing.style} onChange={e => setEditing({ ...editing, style: e.target.value })} /></Field><Field label="语速"><select value={editing.speed ?? 'default'} onChange={e => setEditing({ ...editing, speed: e.target.value === 'default' ? null : +e.target.value })}><option value="default">跟随默认</option>{[-50, -20, 0, 10, 20, 50, 100].map(v => <option key={v} value={v}>{1 + v / 100} 倍</option>)}</select></Field><Toggle value={editing.muted} title="静音该观众" detail="停止播报，并禁止其修改互动设置" onChange={muted => setEditing({ ...editing, muted })} /><Toggle value={editing.locked} title="锁定偏好" detail="仍然播报，但不再接受修改指令" onChange={locked => setEditing({ ...editing, locked })} /><div className="modal-actions"><button className="button secondary" onClick={() => setEditing({ ...editing, voice: '', style: '', speed: null })}>恢复默认配置</button><button className="button primary" onClick={() => void action('viewer', async () => { const { voice, style, speed, muted, locked } = editing; await api(`/viewers/${encodeURIComponent(editing.uid)}`, { voice, style, speed, muted, locked }, 'PATCH'); await load(); setEditing(null); }, '观众偏好已保存')}>保存档案</button></div></Modal>}
    {simulate && <Modal title="本地指令测试" close={() => setSimulate(false)}><p className="muted">只在本服务中模拟事件，不发送到哔哩哔哩。播放器开启时，指令确认与普通文字都会进入真实合成队列，并可能消耗语音额度。</p><Field label="测试 UID"><input value={sim.uid} onChange={e => setSim({ ...sim, uid: e.target.value })} /></Field><Field label="显示昵称"><input value={sim.username} onChange={e => setSim({ ...sim, username: e.target.value })} /></Field><Field label="测试弹幕"><input value={sim.text} onChange={e => setSim({ ...sim, text: e.target.value })} /></Field><button className="button primary full" onClick={() => void action('simulate', async () => { const result = await api('/simulate', sim); notify(String(result.command || result.skipped || (result.queued ? '已进入播报队列' : '已处理'))); await load(); })}>执行本地测试</button></Modal>}
  </>;
}
function Designs({ action, reloadVoices, busy }: { action: Action; reloadVoices: () => Promise<void>; busy: string }) {
  const [items, setItems] = useState<Design[]>([]), [selected, setSelected] = useState<Design | null>(null), [slot, setSlot] = useState(''), [confirmed, setConfirmed] = useState(false);
  async function load() { setItems(await api<Design[]>('/designs')); }
  useEffect(() => { void load(); const t = setInterval(() => void load(), 5000); return () => clearInterval(t); }, []);
  const names: Record<string, string> = { pending: '待主播审核', processing: '生成中', ready: '已绑定', rejected: '已关闭', uncertain: '需要核对' };
  return <><div className="design-banner"><span><WandSparkles size={29} /></span><div><h2>描述一种声音，让它成为专属。</h2><p>观众发送 <code>#定制 声音描述</code> 提交申请。生成会使用「声音复刻」的槽位与更新次数，和标准 TTS 字数包分开。</p></div></div><section className="card"><div className="card-head"><h2>音色申请</h2><Badge>{items.filter(i => i.status === 'pending').length} 个待处理</Badge></div>{!items.length ? <Empty icon={WandSparkles} title="灵感还在路上">收到 #定制 指令后，申请会出现在这里。未经主播操作，不会调用生成接口。</Empty> : <div className="design-list">{items.map(d => <article className="design-item" key={d.id}><div><div className="inline"><b>{d.username}</b><Badge tone={d.status === 'ready' ? 'green' : d.status === 'uncertain' ? 'red' : 'purple'}>{names[d.status]}</Badge><small>UID {d.uid}</small></div><p>{d.prompt}</p><small>{d.speaker || '尚未分配槽位'} {d.detail && ` · ${d.detail}`}</small></div>{d.status === 'pending' && <div className="button-group"><button className="button secondary" disabled={!!busy} onClick={() => void action('reject', async () => { await api(`/designs/${d.id}/reject`, {}); await load(); })}>拒绝</button><button className="button primary" disabled={!!busy} onClick={() => { setSelected(d); setSlot(''); setConfirmed(false); }}>审核并生成</button></div>}{d.status === 'uncertain' && <div className="recovery"><p>先到火山控制台核对此槽位，避免重复消耗次数。</p><button className="button secondary" onClick={() => void action('resolve', async () => { await api(`/designs/${d.id}/resolve`, { ready: true }); await load(); await reloadVoices(); })}>云端已成功，绑定</button><button className="text-button" onClick={() => void action('resolve', async () => { await api(`/designs/${d.id}/resolve`, { ready: false }); await load(); })}>确认失败，关闭</button></div>}</article>)}</div>}</section>{selected && <Modal title="生成并绑定专属音色" close={() => { if (busy !== 'design') setSelected(null); }}><p>为 <b>{selected.username}</b> 创建：{selected.prompt}</p><Field label="火山空音色槽位 ID" hint="从音色设计 / 声音复刻控制台复制 S_ 开头的槽位 ID。"><input placeholder="S_…" value={slot} onChange={e => setSlot(e.target.value.trim())} /></Field><div className="notice warning"><p>此操作会消耗该槽位 1 次更新机会，并可能覆盖槽位现有声音。本服务只能检测本地绑定，无法判断云端槽位是否为空。生成结果未知时不会自动重试。</p></div><label className="checkbox"><input type="checkbox" checked={confirmed} onChange={e => setConfirmed(e.target.checked)} />我已在火山控制台确认这是可用的空槽位</label><button className="button primary full" disabled={!confirmed || !/^S_[a-zA-Z0-9_-]{3,100}$/.test(slot) || !!busy} onClick={() => void action('design', async () => { await api(`/designs/${selected.id}/approve`, { speaker: slot, confirmEmptySlot: true }); await reloadVoices(); await load(); setSelected(null); }, '专属音色已生成并绑定')}>{busy === 'design' ? <LoaderCircle className="spin" size={17} /> : <WandSparkles size={17} />}{busy === 'design' ? '正在生成，请保持页面开启…' : '消耗 1 次更新机会并生成'}</button></Modal>}</>;
}
function EventSettings({ settings, save }: { settings: Settings; save: (patch: Partial<Settings>) => Promise<boolean> }) {
  const [draft, setDraft] = useState(() => ({ eventSpeech: { ...settings.eventSpeech }, interactionActions: { ...settings.interactionActions }, commandFeedback: settings.commandFeedback, giftCooldownSeconds: settings.giftCooldownSeconds, likeCooldownSeconds: settings.likeCooldownSeconds, entryCooldownSeconds: settings.entryCooldownSeconds }));
  const [saving, setSaving] = useState(false);
  return <div className="event-settings"><section className="notice event-notice"><Radio size={21} /><div><b>接收照常，按需出声</b><p>保存后立即生效。关闭的类型仍出现在活动记录中，不排队、不调用豆包。普通弹幕默认开启，新增类型默认关闭。</p></div></section>
    <div className="event-grid">{eventTypes.map(type => <section className="card event-card" key={type}><div className="event-code">{type}</div><Toggle title={eventLabels[type]} value={draft.eventSpeech[type]} onChange={value => setDraft(d => ({ ...d, eventSpeech: { ...d.eventSpeech, [type]: value } }))} /><p>{eventDescriptions[type][0]}</p><div className="speech-example"><Volume2 size={15} /><span>{eventDescriptions[type][1]}</span></div>{type === 'interaction' && <div className="interaction-options">{(Object.keys(interactionLabels) as InteractionAction[]).map(action => <Toggle key={action} title={`${action} · ${interactionLabels[action]}`} detail={interactionExamples[action]} value={draft.interactionActions[action]} onChange={value => setDraft(d => ({ ...d, interactionActions: { ...d.interactionActions, [action]: value } }))} />)}</div>}</section>)}</div>
    <section className="card settings-card"><div className="card-head"><h2><Terminal size={20} />指令语音反馈</h2><Badge tone="purple">独立开关</Badge></div><Toggle title="朗读设置确认与查询结果" value={draft.commandFeedback} detail="不受普通弹幕开关影响；仍遵守总暂停、静音、队列与额度保护。" onChange={value => setDraft(d => ({ ...d, commandFeedback: value }))} /><div className="command-examples"><p><code>#音色 小何</code> 小明开始使用小何音色。</p><p><code>#风格 开心俏皮</code> 小明改了语音风格：开心俏皮。</p><p><code>#语速 1.2</code> 小明将语速改为 1.2 倍。</p><p><code>#查询</code> 小明当前音色小何，语速 1.2 倍，风格为开心俏皮。</p></div><p className="caption">#重置、#定制 也会有简短确认；#我的音色 与 #查询 等效。不会直接朗读原始指令。查询播报每人至少间隔 10 秒；较长的风格反馈会按单条字数上限截短。</p></section>
    <section className="card settings-card"><div className="card-head"><h2><ShieldCheck size={20} />防刷屏与冷却</h2></div><div className="form-grid">{([['giftCooldownSeconds', '同一观众、同种礼物（秒）', 1, 300], ['likeCooldownSeconds', '同一观众点赞（秒）', 1, 300], ['entryCooldownSeconds', '同一观众欢迎（秒）', 10, 600]] as const).map(([key, label, min, max]) => <Field label={label} key={key}><input type="number" min={min} max={max} value={draft[key]} onChange={e => setDraft(d => ({ ...d, [key]: +e.target.value }))} /></Field>)}</div><p className="muted">进场与进场特效共用欢迎冷却，先到且开启的事件播报一次。礼物按单条通知数量读出，冷却内的后续通知只记日志，不累加成连击总数。点赞只感谢，不推算次数。关注、分享等同一行为固定冷却 10 秒。</p><p className="caption">缺少 UID 时使用默认声音，按匿名事件组限频，不会根据昵称关联观众。关闭播放器时不积压播报；开启后从新事件开始。</p></section>
    <div className="save-bar"><span>每类事件都可独立控制 · 保存到本机</span><button className="button primary" disabled={saving} onClick={async () => { setSaving(true); try { await save(draft); } finally { setSaving(false); } }}><Check size={17} />{saving ? '正在保存…' : '保存事件播报设置'}</button></div>
  </div>;
}
function Logs({ logs }: { logs: LogEntry[] }) {
  const [filter, setFilter] = useState('all'), [type, setType] = useState('all'), [events, setEvents] = useState<Record<string, unknown> | null>(null), [inspectType, setInspectType] = useState<EventType>('message');
  const list = logs.filter(l => (type === 'all' || l.eventType === type) && (filter === 'all' || filter === 'command' && (l.kind.startsWith('command') || l.eventType === 'command') || filter === 'error' && (l.kind.includes('error') || l.kind === 'invalid') || filter === 'speech' && ['speech', 'cached'].includes(l.kind) || l.kind === filter));
  return <><div className="toolbar log-toolbar"><div className="filter-row">{[['all', '全部记录'], ['speech', '语音合成'], ['command', '互动指令'], ['queued', '已排队'], ['disabled', '关闭播报'], ['duplicate', '重复'], ['cooldown', '冷却'], ['error', '异常']].map(([id, label]) => <button className={filter === id ? 'selected' : ''} key={id} onClick={() => setFilter(id)}>{label}</button>)}</div><div className="button-group"><select aria-label="记录事件类型" value={type} onChange={e => setType(e.target.value)}><option value="all">所有事件类型</option>{eventTypes.map(t => <option key={t} value={t}>{eventLabels[t]}</option>)}<option value="command">指令反馈</option></select><button className="button secondary" onClick={() => void api<Record<string, unknown>>('/events').then(setEvents).catch(e => setEvents({ error: e.message }))}><Terminal size={16} />最近事件结构</button></div></div><section className="card">{list.length ? <LogList logs={list} /> : <Empty icon={Activity} title="暂无相关记录">实时显示最近 200 条活动，服务保留最近 3,000 条。</Empty>}</section>{events !== null && <Modal title="LAPLACE 最近事件结构" close={() => setEvents(null)}><p className="muted">按类型保留本次服务启动后最近一条事件，包括关闭播报、重复及字段异常的事件。source=bridge 表示桥接接收，simulation 表示本地模拟；仅显示用于解析的字段，不包含密钥或 SC 举报 token。</p><Field label="检查事件类型"><select value={inspectType} onChange={e => setInspectType(e.target.value as EventType)}>{eventTypes.map(t => <option key={t} value={t}>{eventLabels[t]} · {t}{events[t] ? ' · 已接收' : ''}</option>)}</select></Field><pre className="event-json">{events.error ? JSON.stringify(events, null, 2) : events[inspectType] ? JSON.stringify(events[inspectType], null, 2) : '本次服务启动后尚未收到此类型。'}</pre></Modal>}</>;
}
function SettingsPanel({ status, voices, save, action, notify }: { status: Status; voices: Voice[]; save: (s: Partial<Settings>) => Promise<boolean>; action: Action; notify: (s: string) => void }) {
  const [draft, setDraft] = useState({ ...status.settings }), [connection, setConnection] = useState({ apiToken: '', credentialSource: '' });
  const [authMode, setAuthMode] = useState('key'), [credentials, setCredentials] = useState({ apiKey: '', appId: '', accessKey: '' });
  useEffect(() => { void api<typeof connection>('/connection').then(setConnection).catch(e => notify(e.message)); }, []);
  const change = <K extends keyof Settings>(key: K, value: Settings[K]) => setDraft(d => ({ ...d, [key]: value }));
  async function copy(value: string) { try { await navigator.clipboard.writeText(value); notify('已复制'); } catch { notify('浏览器不允许复制，请手动选择文本。'); } }
  return <div className="settings-layout"><div><section className="card settings-card"><div className="card-head"><h2><Link2 size={20} />连接 LAPLACE</h2><Badge tone="purple">本机接入</Badge></div><Field label="运行模式"><select value={draft.mode} onChange={e => change('mode', e.target.value as Settings['mode'])}><option value="bridge">精准互动模式 · Event Bridge + 本地播放器（推荐）</option><option value="api">兼容 API 模式 · LAPLACE 播放 / 无观众身份</option></select></Field><Field label="直播间房间号"><input inputMode="numeric" value={draft.roomId} onChange={e => change('roomId', e.target.value)} /></Field><div className="setup-steps"><p><b>1</b>在 LAPLACE 设置 → Event Bridge 中填写：</p><div className="config-grid"><div><small>主机</small><code>127.0.0.1</code></div><div><small>端口</small><code>{location.port === '5173' ? '23000' : location.port || '23000'}</code></div></div><Field label="密码 / 本地 API 密钥"><div className="copy-field"><input readOnly type="password" value={connection.apiToken} /><button className="icon-button" aria-label="复制本地 API 密钥" onClick={() => void copy(connection.apiToken)}><Copy size={17} /></button></div></Field><p><b>2</b>打开 Event Bridge 连接，并勾选自动重连。</p><p><b>3</b>精准互动模式下，关闭 LAPLACE「自动语音播报」，本后台播放器会默认自动开启。若浏览器拦截声音，点击页面任意位置即可启用。</p></div><details><summary>使用自定义 TTS API 的接入信息</summary><p>LAPLACE 默认只传 token、text、voice、instructions，不带 UID。兼容模式使用统一音色；精准模式此接口返回静音，避免双重播报。</p><div className="copy-field"><input readOnly value={`http://127.0.0.1:${location.port === '5173' ? '23000' : location.port || '23000'}/v1/tts`} /><button className="icon-button" aria-label="复制 API 地址" onClick={() => void copy(`http://127.0.0.1:${location.port === '5173' ? '23000' : location.port || '23000'}/v1/tts`)}><Copy size={17} /></button></div><p>API 密钥填上方本地密钥；音色填「小何」等名称，留空则跟随默认。指令框填说话风格。</p></details></section>
      <section className="card settings-card"><div className="card-head"><h2><Mic2 size={20} />火山引擎凭据</h2><Badge tone={status.configured ? 'green' : ''}>{status.configured ? '已配置' : '待配置'}</Badge></div><p className="muted">凭据只发往本机服务，由服务调用火山官方接口；在本地加密保存，页面不会回显。</p><div className="filter-row"><button className={authMode === 'key' ? 'selected' : ''} onClick={() => setAuthMode('key')}>新版 API Key</button><button className={authMode === 'legacy' ? 'selected' : ''} onClick={() => setAuthMode('legacy')}>App ID + Access Token</button></div>{authMode === 'key' ? <Field label="火山语音服务 API Key"><input type="password" autoComplete="new-password" placeholder="填入你的 API Key" value={credentials.apiKey} onChange={e => setCredentials({ ...credentials, apiKey: e.target.value })} /></Field> : <><Field label="App ID"><input value={credentials.appId} onChange={e => setCredentials({ ...credentials, appId: e.target.value })} /></Field><Field label="Access Token"><input type="password" autoComplete="new-password" value={credentials.accessKey} onChange={e => setCredentials({ ...credentials, accessKey: e.target.value })} /></Field></>}<button className="button secondary" onClick={() => void action('credentials', async () => { await api('/credentials', authMode === 'key' ? { apiKey: credentials.apiKey } : { appId: credentials.appId, accessKey: credentials.accessKey }); setCredentials({ apiKey: '', appId: '', accessKey: '' }); }, '凭据已加密保存，可前往音色实验室试听')}>保存凭据</button>{connection.credentialSource === 'environment' && <p className="caption">当前环境变量优先于页面保存的凭据。</p>}</section>
      <section className="card settings-card"><div className="card-head"><h2><SlidersHorizontal size={20} />播报规则</h2></div><div className="form-grid"><Field label="默认音色"><select value={draft.defaultVoice} onChange={e => change('defaultVoice', e.target.value)}>{voices.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}</select></Field><Field label="默认语速"><select value={draft.speechRate} onChange={e => change('speechRate', +e.target.value)}>{[-50, -20, 0, 10, 20, 50, 100].map(v => <option key={v} value={v}>{1 + v / 100} 倍</option>)}</select></Field></div><Field label="默认说话风格"><textarea rows={2} maxLength={200} placeholder="例如：轻松自然，语气有活力" value={draft.defaultStyle} onChange={e => change('defaultStyle', e.target.value)} /></Field><div className="form-grid">{([['maxChars', '单条最多字数', 5, 500], ['maxQueue', '待播队列长度', 1, 50], ['cooldownSeconds', '指令冷却（秒）', 0, 300]] as const).map(([key, label, min, max]) => <Field key={key} label={label}><input type="number" min={min} max={max} value={draft[key]} onChange={e => change(key, +e.target.value)} /></Field>)}</div><Toggle value={draft.announceUsername} title="朗读观众昵称" onChange={v => change('announceUsername', v)} /><Toggle value={draft.allowStyles} title="允许 #风格 指令" onChange={v => change('allowStyles', v)} /><Toggle value={draft.allowDesignRequests} title="允许 #定制 申请" detail="只记录申请，生成仍由主播操作" onChange={v => change('allowDesignRequests', v)} /><Field label="屏蔽词" hint="每行一个，命中整词即跳过播报。"><textarea rows={3} value={draft.blockedWords} onChange={e => change('blockedWords', e.target.value)} /></Field><details><summary>自定义 API 的允许来源</summary><Field label="CORS 来源（每行一个）"><textarea value={draft.allowedOrigins.join('\n')} onChange={e => change('allowedOrigins', e.target.value.split('\n').filter(Boolean))} /></Field></details></section><div className="save-bar"><span>更改后记得保存</span><button className="button primary" onClick={() => void save({ ...draft, enabled: status.settings.enabled })}><Check size={17} />保存接入与播报设置</button></div></div>
    <aside><section className="card settings-card quota-card"><div className="card-head"><h2><ShieldCheck size={19} />试用额度保护</h2></div><div className="quota-number">{fmt(status.used)}<small>/ {fmt(draft.budget)} 字</small></div><div className="progress"><span style={{ width: `${Math.min(100, status.used / Math.max(1, draft.budget) * 100)}%` }} /></div><p className="caption">本机合成统计 + 手动填入的历史用量，不是火山实时余额。达到上限后停止调用；超时请求按预估字数保守计入。</p><Field label="标准音色累计上限（字）"><input type="number" min="0" value={draft.budget} onChange={e => change('budget', +e.target.value)} /></Field><Field label="接入前已使用（字）"><input type="number" min="0" value={draft.usedBefore} onChange={e => change('usedBefore', +e.target.value)} /></Field><hr /><Field label="专属音色合成上限（字）" hint={`独立资源池 · 本机已用 ${fmt(status.cloneUsed)} 字。填 0 可禁止专属音色合成。`}><input type="number" min="0" value={draft.cloneBudget} onChange={e => change('cloneBudget', +e.target.value)} /></Field><p className="caption">音色设计的更新次数在火山槽位中计数，不包含在此字数统计。请在火山控制台核对试用范围与有效期。</p></section><section className="tip-card"><Sparkles size={21} /><h3>开播前的小检查</h3><p>连接弹幕桥 → 关闭 LAPLACE 自动播报 → 确认本地播放器正在监听。</p><p>保持后台页面开启，并让 OBS 捕获浏览器的播放声音。</p></section></aside></div>;
}
createRoot(document.getElementById('root')!).render(<App />);
